import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {join,dirname,resolve} from 'node:path';
import {createCoverageMap} from 'istanbul-lib-coverage';
import {instrumentTypeScriptWithCoverage} from '../scripts/run-istanbul-bun-coverage';
import {createOwnedTestDirectory} from '../tests/helpers/owned-test-directory';
import {sourceHash} from '../scripts/quality-inventory';
const root=process.cwd(),storage=createOwnedTestDirectory('memory-remote-diagnostic-');
const paths=["src/infrastructure/database/extraction-batch-events.ts","src/infrastructure/database/event-log.ts","src/infrastructure/database/projection-payload.ts","tests/infrastructure/database/extraction-batch-replay.test.ts"];

const tests=paths.filter(path=>path.endsWith('.test.ts'));
const mode=process.argv[2]??'measure';if(!['measure','faults'].includes(mode))throw Error('Invalid mode');
const originals=new Map(paths.map(path=>[path,readFileSync(path,'utf8')]));
const typePath='src/domain/ports/operation-admission.ts',typeHash=sourceHash(readFileSync(typePath,'utf8'));
function put(path:string,content:string){mkdirSync(dirname(join(storage.dir,path)),{recursive:true});writeFileSync(join(storage.dir,path),content.replace(/from "commander"/g,'from '+JSON.stringify(Bun.resolveSync('commander',root))));}
const runs:any[]=[];

const faults=[{"path":"src/infrastructure/database/extraction-batch-events.ts","kind":"omit-wrapper-kind","from":"event.kind !== \"projection\" || ","to":"","pattern":"wrong kind"},{"path":"src/infrastructure/database/extraction-batch-events.ts","kind":"omit-wrapper-operation","from":"event.operation !== \"add\" || ","to":"","pattern":"wrong operation"},{"path":"src/infrastructure/database/extraction-batch-events.ts","kind":"allow-extra-payload","from":"Object.keys(payload).length !== 1 ||","to":"","pattern":"extra payload"},{"path":"src/infrastructure/database/extraction-batch-events.ts","kind":"omit-project-binding","from":"scope.project !== batch.project || ","to":"","pattern":"project mismatch"},{"path":"src/infrastructure/database/extraction-batch-events.ts","kind":"omit-visibility-binding","from":"scope.visibility !== \"project\" || ","to":"","pattern":"scope widening"},{"path":"src/infrastructure/database/extraction-batch-events.ts","kind":"omit-workspace-binding","from":"scope.workspace !== undefined ||","to":"","pattern":"workspace scope"},{"path":"src/infrastructure/database/extraction-batch-events.ts","kind":"omit-completion-time","from":"event.observedAt.toISOString() !== batch.extractedAt || ","to":"","pattern":"observed time"},{"path":"src/infrastructure/database/extraction-batch-events.ts","kind":"omit-occurred-time","from":"event.occurredAt.toISOString() !== batch.extractedAt ||","to":"","pattern":"occurred time"},{"path":"src/infrastructure/database/extraction-batch-events.ts","kind":"omit-source-binding","from":"provenance.source !== \"memory-extraction\" || ","to":"","pattern":"provenance source"},{"path":"src/infrastructure/database/extraction-batch-events.ts","kind":"omit-method-binding","from":"provenance.method !== \"extraction-batch-v1\" ||","to":"","pattern":"provenance method"},{"path":"src/infrastructure/database/extraction-batch-events.ts","kind":"omit-session-binding","from":"JSON.stringify(provenance.sourceIds) !== JSON.stringify([batch.sessionId]) ||","to":"","pattern":"provenance session"},{"path":"src/infrastructure/database/extraction-batch-events.ts","kind":"allow-wrapper-child-identity","from":"batch.facts.some(fact => fact.uuid === event.eventId)","to":"false","pattern":"wrapper child collision"},{"path":"src/infrastructure/database/extraction-batch-events.ts","kind":"lose-wrapper-provenance","from":"sourceIds: [event.eventId]","to":"sourceIds: [fact.uuid]","pattern":"governance preserves"},{"path":"src/infrastructure/database/extraction-batch-events.ts","kind":"weaken-effect-consent","from":"consent: event.consent","to":"consent: {status:\"not_required\",scopes:[]}","pattern":"governance preserves"},{"path":"src/infrastructure/database/extraction-batch-events.ts","kind":"weaken-effect-privacy","from":"privacy: effectPrivacy(event.privacy, fact.metadata)","to":"privacy: {redactionState:\"none\",containsSensitiveContent:false}","pattern":"effect privacy|governance preserves"},{"path":"src/infrastructure/database/event-log.ts","kind":"omit-source-child-registration","from":"[event, ...effects ?? []]","to":"[event]","pattern":"collision in either"},{"path":"src/infrastructure/database/event-log.ts","kind":"allow-source-identity-conflict","from":"if (existing !== undefined && existing !== memberIdentity) throw new Error(\"Conflicting event identity\");","to":"","pattern":"collision in either"},{"path":"src/infrastructure/database/event-log.ts","kind":"resort-expanded-effects","from":"registry.replay(expanded,","to":"registry.replay(sortMemoryEvents(expanded),","pattern":"after complete source record"},{"path":"src/infrastructure/database/projection-payload.ts","kind":"omit-complete-effect-validation","from":"for (const effect of effects) assertProjectionPayload(effect);","to":"","pattern":"invalid later metadata"},{"path":"src/infrastructure/database/event-log.ts","kind":"weaken-derived-governance","from":"if (!context.batchEffects.has(event.eventId)) return entry;","to":"return entry;","pattern":"governance preserves"},{"path":"src/infrastructure/database/event-log.ts","kind":"extend-derived-expiry","from":"if (entry.expiresAt && (!expiresAt || entry.expiresAt < expiresAt)) expiresAt = entry.expiresAt;","to":"","pattern":"derived expiry"}];

try {
 for(const [path,content]of originals){
  for(const match of content.matchAll(/(?:from\s+|import\s*\()\s*["'](\.[^"']+)["']/g)) {
   const target=resolve(dirname(path),match[1]).replace(/\.js$/,'.ts'),local=target.slice(root.length+1).replaceAll('\\','/');
   if(!paths.includes(local))put(local,'export * from '+JSON.stringify(target.replaceAll('\\','/'))+';');
  }
  for(const match of content.matchAll(/source\("([^"]+)"\)/g)){
   const local=match[1].startsWith('src/')?match[1]:'src/'+match[1];if(!paths.includes(local))put(local,'export * from '+JSON.stringify(resolve(local).replaceAll('\\','/'))+';');
  }
 }
 put('capture.ts','import {afterAll} from "bun:test";import {writeFileSync} from "node:fs";afterAll(()=>writeFileSync("coverage.json",JSON.stringify((globalThis as any).__coverage__)));');
 put('bunfig.toml','[test]\ncoverage=false\npreload=['+JSON.stringify(join(root,'tests/test-setup.ts').replaceAll('\\','/'))+(mode==='measure'?',"./capture.ts"':'')+']\n');
 for(const fault of [null,...(mode==='faults'?faults:[])]) {
  for(const [path,content]of originals)put(path,mode==='measure'?instrumentTypeScriptWithCoverage(content,resolve(path)).code:content);
  if(fault){let content=originals.get(fault.path)!;const index=content.indexOf(fault.from);if(index<0)throw Error('Missing fault '+fault.kind);put(fault.path,content.slice(0,index)+fault.to+content.slice(index+fault.from.length));}
  const command=[process.execPath,'test','--timeout','15000',...tests,...(fault?['--test-name-pattern',fault.pattern]:[])];
  const child=Bun.spawnSync(command,{cwd:storage.dir,env:{...process.env,TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe',timeout:180000});
  const output=new TextDecoder().decode(child.stdout)+new TextDecoder().decode(child.stderr);runs.push({fault,command,exit:child.exitCode,output});
  writeFileSync('.git/q100-batch-replay-diagnostic-progress.json',JSON.stringify({runs},null,2));
  if(!fault&&child.exitCode!==0)throw Error('Control failed\n'+output);
  if(fault&&child.exitCode!==0&&!output.includes('(fail)'))throw Error('Fault did not reach assertions\n'+output);
 }
 let measurement;
 if(mode==='measure'){
  const raw=JSON.parse(readFileSync(join(storage.dir,'coverage.json'),'utf8')),map=createCoverageMap(raw);
  measurement={rawCoverage:raw,files:paths.map(path=>{const measured=map.fileCoverageFor(resolve(path)),data=measured.data;return {path,sourceHash:sourceHash(originals.get(path)!),metrics:measured.toSummary().data,uncoveredBranches:Object.entries(data.b).flatMap(([id,hits])=>hits.flatMap((count,index)=>count===0?[{id,index,location:data.branchMap[id]?.locations[index]}]:[])),uncoveredFunctions:Object.entries(data.f).filter(([,hits])=>hits===0).map(([id])=>data.fnMap[id])};})};
  console.log(JSON.stringify(measurement.files.map(file=>({path:file.path,metrics:file.metrics}))));
 }else console.log(JSON.stringify(runs.map(run=>({fault:run.fault?.kind,exit:run.exit}))));
 writeFileSync(`.git/q100-batch-replay-${mode}.json`,JSON.stringify({recordedAt:new Date().toISOString(),runtime:Bun.version,scope:'Scoped diagnostic only; child process instrumentation is not aggregated. No full quality acceptance.',sourceInputs:[...paths.map(path=>({path,sourceHash:sourceHash(originals.get(path)!)})),{path:typePath,sourceHash:typeHash}],runs,measurement,source:readFileSync('.git/q100-batch-replay-diagnostic.ts','utf8')},null,2)+'\n');
} finally { storage.cleanup(); }

