import{readFileSync,writeFileSync,mkdirSync,statfsSync}from'node:fs';
import{join,resolve}from'node:path';
import{createOwnedTestDirectory}from'../tests/helpers/owned-test-directory';
const free=statfsSync(process.cwd());if(free.bavail*free.bsize<536870912)throw Error('Legacy probe needs512MiB headroom');
const storage=createOwnedTestDirectory('memory-batch-legacy-consumer-');
try{
 const archive=join(storage.dir,'tag.zip'),tree=join(storage.dir,'tag');mkdirSync(tree);
 const git=Bun.spawnSync(['git','archive','--format=zip','--output='+archive,'v4.0.3','src'],{stdout:'pipe',stderr:'pipe',timeout:30000});if(git.exitCode!==0)throw Error(new TextDecoder().decode(git.stderr));
 const script=join(storage.dir,'expand.ps1');writeFileSync(script,'param([string]$Archive,[string]$Destination)\n$ErrorActionPreference="Stop"\nExpand-Archive -LiteralPath $Archive -DestinationPath $Destination\n');
 const expanded=Bun.spawnSync(['powershell.exe','-NoProfile','-NonInteractive','-File',script,archive,tree],{stdout:'pipe',stderr:'pipe',timeout:45000});if(expanded.exitCode!==0)throw Error(new TextDecoder().decode(expanded.stderr));
 const source=(p:string)=>JSON.stringify(resolve(p).replaceAll('\\','/'));
 const program=`
import{strict as assert}from'node:assert';import{writeFileSync}from'node:fs';import{join}from'node:path';
import{rebuildProjectionsWithReport}from ${source(join(tree,'src/infrastructure/database/event-log.ts'))};
import{OwnedDatabase}from ${source('src/infrastructure/database/owned-database.ts')};
import{createSchema}from ${source('src/infrastructure/database/schema.ts')};
import{MemoryEventEnvelope}from ${source('src/domain/entities/memory-event.ts')};
const dir=process.argv[2],db=new OwnedDatabase(join(dir,'synthetic.db')),log=join(dir,'events-a.jsonl'),time='2026-09-28T10:00:00.000Z';
try{
createSchema(db);db.run("INSERT INTO facts(uuid,type,project,content,observed_at) VALUES('preserved','learning','synthetic','existing synthetic fact',?)",[time]);
const event=MemoryEventEnvelope.create({eventId:'batch',machineId:'synthetic',sequence:1,kind:'projection',operation:'add',occurredAt:new Date(time),observedAt:new Date(time),scope:{project:'synthetic',visibility:'project'},provenance:{source:'memory-extraction',actor:'memory',method:'extraction-batch-v1',sourceIds:['session']},privacy:{redactionState:'none',containsSensitiveContent:false},consent:{status:'not_required',scopes:[]},causality:{parentEventIds:[],relatedEventIds:[],supersedesEventIds:[]},payload:{extractionBatch:{version:1,sessionId:'session',inputIdentity:'v1:'+'a'.repeat(64),project:'synthetic',provider:'synthetic',model:'synthetic',extractedAt:time,result:{added:1,updated:0,superseded:0,skipped:0},facts:[{uuid:'new-fact',type:'learning',content:'new synthetic fact'}]}}});
writeFileSync(log,JSON.stringify(event.toJSON())+'\\n');let result,error;
try{result=await rebuildProjectionsWithReport(db,log);}catch(cause){error=String(cause);}
using rows=db.prepare('SELECT uuid FROM facts');console.log(JSON.stringify({result,error,remainingFacts:rows.all()}));assert(error,'An unsupported consumer must refuse a batch without deleting projections');
}finally{db.close();}
`;
 const path=join(storage.dir,'probe.ts');writeFileSync(path,program);
 const result=Bun.spawnSync([process.execPath,path,storage.dir],{cwd:storage.dir,env:{...process.env,HOME:storage.dir,USERPROFILE:storage.dir,XDG_CONFIG_HOME:join(storage.dir,'config'),XDG_DATA_HOME:join(storage.dir,'data'),MEMORY_HOME:join(storage.dir,'legacy'),TEMP:storage.dir,TMP:storage.dir,TMPDIR:storage.dir},stdout:'pipe',stderr:'pipe',timeout:30000});
 const output=new TextDecoder().decode(result.stdout)+new TextDecoder().decode(result.stderr);
 const revision=Bun.spawnSync(['git','rev-parse','v4.0.3^{commit}'],{stdout:'pipe',stderr:'pipe'});if(revision.exitCode!==0)throw Error('Missing tag revision');
 writeFileSync('.git/q100-batch-replay-old-consumer.json',JSON.stringify({tag:'v4.0.3',revision:new TextDecoder().decode(revision.stdout).trim(),scope:'Tagged src tree executes actual old replay with current synthetic schema/OwnedDatabase and current source-envelope producer. Not a registry install or supported-platform acceptance.',exit:result.exitCode,output,program,oldReader:readFileSync(join(tree,'src/infrastructure/database/event-log.ts'),'utf8'),oldRegistry:readFileSync(join(tree,'src/application/services/projection-registry.ts'),'utf8'),source:readFileSync('.git/q100-batch-replay-old-consumer.ts','utf8')},null,2));console.log(output);if(result.exitCode!==1)throw Error('Expected retained legacy consumer RED');
}finally{storage.cleanup();}

